/** Private closed readback. No fixture mutation/evaluation/promotion, arbitrary SQL or posted score. */
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {SPECIALIST_MODULES,GAIN_MODULES,SPECIALIST_PHASES} from './assistant-specialist-governance-experience.mjs';
const uuid=v=>typeof v==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
export function specialistInvocation(value,phase){assert(value&&typeof value==='object'&&!Array.isArray(value));assert.equal(value.phase,phase);const job=['baseline:','consume:','reload:','after_rollback:'].some(prefix=>phase.startsWith(prefix));assert.deepEqual(Object.keys(value).sort(),job?['jobId','phase']:['phase']);if(job)assert(uuid(value.jobId));return structuredClone(value);}
export async function createAssistantSpecialistNativeReadback({root,owner,fixture}){
 assert(fixture?.state==='native_prerequisites_prepared_not_experienced'&&fixture.actors.reviewers.length===2);const actors=[fixture.actors.operator,...fixture.actors.reviewers];assert(actors.every(a=>uuid(a.userId)&&uuid(a.personId)));assert.equal(new Set(actors.map(a=>a.userId)).size,3);
 const urls=[process.env.DATABASE_URL,process.env.MIGRATION_DATABASE_URL].map(v=>new URL(v));for(const u of urls){assert(['postgres:','postgresql:'].includes(u.protocol));assert(['127.0.0.1','localhost','[::1]'].includes(u.hostname));assert.equal(u.port,'5433');assert(/^aihr_assistant_browser_[a-f0-9]{16}$/.test(u.pathname.slice(1)));assert(!u.hash&&[...u.searchParams].every(([k,v])=>k==='sslmode'&&v==='disable'));}assert.equal(urls[0].pathname,urls[1].pathname);assert.equal(decodeURIComponent(urls[0].username),'ai_hr_app');assert.notEqual(urls[0].username,urls[1].username);
 const configured=urls.map(u=>u.toString()),database=urls[0].pathname.slice(1),ownerRole=decodeURIComponent(urls[1].username),require=createRequire(join(root,'package.json')),{sql}=require('drizzle-orm');
 const db=await import(pathToFileURL(join(root,'db/client.ts')).href),release=await import(pathToFileURL(join(root,'core/module-agent-releases.ts')).href),entitlements=await import(pathToFileURL(join(root,'core/entitlements.ts')).href);
 function physical(row,role,privileged){assert.equal(row.database,database);assert.equal(row.role,role);assert(['127.0.0.1','::1'].includes(row.address));assert.equal(row.port,5433);assert.equal(row.readonly,'on');assert.equal(row.isolation,'read committed');assert.equal(row.privileged,privileged);}
 async function ownerRead(run){return owner.client.begin('isolation level read committed read only',async tx=>{const[row]=await tx`select current_user as role,current_database() as database,host(inet_server_addr()) as address,inet_server_port() as port,current_setting('transaction_read_only') as readonly,current_setting('transaction_isolation') as isolation,rolsuper or rolbypassrls as privileged from pg_roles where rolname=current_user`;physical(row,ownerRole,true);return run(tx);});}
 async function context(actor){return db.client.begin('isolation level read committed read only',async tx=>{const[role]=await tx`select current_user as role,current_database() as database,host(inet_server_addr()) as address,inet_server_port() as port,current_setting('transaction_read_only') as readonly,current_setting('transaction_isolation') as isolation,rolsuper or rolbypassrls as privileged from pg_roles where rolname=current_user`;physical(role,'ai_hr_app',false);const rows=await tx`select tenant_id,person_id,grants from app.principal(${actor.userId}::uuid)`;assert.equal(rows.length,1);const p=rows[0];assert.equal(p.tenant_id,fixture.tenantId);assert.equal(p.person_id,actor.personId);assert(Array.isArray(p.grants)&&p.grants.every(g=>g&&typeof g.role==='string'&&(g.companyId===null||uuid(g.companyId))));return{tenantId:p.tenant_id,userId:actor.userId,personId:p.person_id,grants:p.grants.map(g=>({...g})),roles:[...new Set(p.grants.map(g=>g.role))]};});}
 async function canonical(actor,run){const ctx=await context(actor);return db.withTenant(ctx,async tx=>{await tx.execute(sql`SET TRANSACTION READ ONLY`);const[row]=await tx.execute(sql`select current_user as role,current_database() as database,host(inet_server_addr()) as address,inet_server_port() as port,current_setting('transaction_read_only') as readonly,current_setting('transaction_isolation') as isolation,rolsuper or rolbypassrls as privileged from pg_roles where rolname=current_user`);physical(row,'ai_hr_app',false);return run(tx,{...ctx,entitlements:await entitlements.resolveEntitlementsTx(tx,ctx.tenantId)});});}
 async function snapshot(){return ownerRead(async tx=>{const[row]=await tx`select(select count(*)::int from public.ai_model_run where tenant_id=${fixture.tenantId}::uuid) as runs,(select count(*)::int from public.ai_agent_candidate where tenant_id=${fixture.tenantId}::uuid) as candidates,(select count(*)::int from public.ai_agent_promotion where tenant_id=${fixture.tenantId}::uuid) as promotions,(select count(*)::int from public.ai_agent_job_receipt where tenant_id=${fixture.tenantId}::uuid) as jobs`;const facts=[];for(const table of ['employment','assignment','reporting_line','leave_request','leave_ledger','claim_request','payroll_batch','payslip','profile_change_request','kb_document']){const[hash]=await tx.unsafe(`select md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by r.id::text),'')) as digest from public.${table} r where r.tenant_id=$1::uuid`,[fixture.tenantId]);facts.push(hash.digest);}return{...row,facts};});}
 let index=0,inFlight=false,baseline;const candidates=new Map(),promotions=new Map(),jobIds=new Set(),consumed=new Map();
 return async invocation=>{assert(!inFlight);inFlight=true;try{
  const p=specialistInvocation(invocation,SPECIALIST_PHASES[index]);assert(same([process.env.DATABASE_URL,process.env.MIGRATION_DATABASE_URL].map(v=>new URL(v).toString()),configured));const state=await snapshot();assert.equal(state.runs,0);if(index===0){assert.equal(state.candidates,0);assert.equal(state.promotions,0);assert.equal(state.jobs,0);for(const actor of actors){const view=await canonical(actor,(tx,ctx)=>release.specialistReviewWorkspaceTx(tx,ctx));assert(view);assert.deepEqual(view.modules.map(row=>row.module).sort(),[...SPECIALIST_MODULES].sort());}baseline=state.facts;index++;return{phase:p.phase,candidates:0,promotions:0,jobs:0,providerRuns:0,nativeEffectsUnchanged:true};}assert(same(state.facts,baseline));
  const[operation,module]=p.phase.split(':');assert(SPECIALIST_MODULES.includes(module));let answer={phase:p.phase,providerRuns:0,nativeEffectsUnchanged:true,module};
  if(['baseline','consume','reload','after_rollback'].includes(operation)){
   const current=await canonical(actors[0],(tx,ctx)=>release.reopenGovernedModuleReadJobTx(tx,ctx,p.jobId));assert.equal(current.jobId,p.jobId);assert.equal(current.jobKind,'specialist');assert.equal(current.changedSinceRun,false);assert.deepEqual(current.results.map(row=>row.module),[module]);assert.equal(current.specialists.length,1);assert.equal(current.specialists[0].assessment.module,module);
   if(operation==='reload'){assert.equal(consumed.get(module),p.jobId);assert(jobIds.has(p.jobId));}else{assert(!jobIds.has(p.jobId));jobIds.add(p.jobId);if(operation==='consume')consumed.set(module,p.jobId);}assert.equal(state.jobs,jobIds.size);
   const view=await canonical(actors[0],(tx,ctx)=>release.specialistReviewWorkspaceTx(tx,ctx));assert(view);const promotion=promotions.has(module)?view.promotions.find(r=>r.id===promotions.get(module)):null;answer={...answer,jobId:current.jobId,jobKind:current.jobKind,changed:current.changedSinceRun,mode:current.mode,used:promotion?.used??0};
  }else{
   const actor=operation==='evaluate1'?actors[1]:operation==='evaluate2'||operation==='promote'||operation==='no_gain'?actors[2]:actors[0],view=await canonical(actor,(tx,ctx)=>release.specialistReviewWorkspaceTx(tx,ctx));assert(view);const matches=view.candidates.filter(r=>r.module===module&&r.version===1);assert.equal(matches.length,1);const c=matches[0];assert.equal(c.playbook,'canonical_followup_v1');if(operation==='create'){assert(c.own);assert(!candidates.has(module));candidates.set(module,c.id);}else assert.equal(c.id,candidates.get(module));
   answer={...answer,candidateId:c.id,playbook:c.playbook,evaluations:c.evaluations,passing:c.passingEvaluators};
   if(operation==='evaluate1'||operation==='evaluate2')assert(!c.own);
   const ps=view.promotions.filter(r=>r.module===module&&r.version===1);
   if(operation==='promote'){assert(GAIN_MODULES.includes(module));assert.equal(ps.length,1);assert(!promotions.has(module));promotions.set(module,ps[0].id);answer={...answer,promotionId:ps[0].id,maximum:ps[0].maximum,used:ps[0].used,retired:ps[0].retired};}
   if(operation==='no_gain'){assert(!GAIN_MODULES.includes(module));answer.promotions=ps.length;}
   if(operation==='rollback'){assert.equal(ps.length,1);assert.equal(ps[0].id,promotions.get(module));answer={...answer,retired:ps[0].retired,used:ps[0].used};}
  }
  index++;return answer;
 }finally{inFlight=false;}};
}
